done
python3 - "$work_tmp" <<'"'PY'
import sys, html, re
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
  def __init__(self): super().__init__(); self.stack=[]; self.tables=[]; self.rows=[]; self.cells=[]; self.text=[]; self.current_table=None
  def handle_starttag(self,t,a):
    self.stack.append(t)
    if t=='table': self.current_table=[]
    if t in ('td','th'): self.text=[]
  def handle_endtag(self,t):
    if t in ('td','th'):
      if self.current_table is not None: self.cells.append(' '.join(''.join(self.text).split()))
      self.text=[]
    if t=='tr':
      if self.current_table is not None and self.cells: self.current_table.append(self.cells); self.cells=[]
    if t=='table':
      if self.current_table is not None: self.tables.append(self.current_table); self.current_table=None
    if self.stack:
      try: self.stack.pop()
      except: pass
  def handle_data(self,d):
    if self.stack and self.stack[-1] in ('td','th'): self.text.append(d)
for fn in ('regular','glance','distance'):
  p=P(); p.feed(Path(sys.argv[1],fn+'.html').read_text())
  print('\\n###',fn)
  for ti,tab in enumerate(p.tables):
    rows=[r for r in tab if any(c for c in r)]
    if rows:
      print('TABLE',ti)
      for r in rows: print(' | '.join(r))
PY"

