trap '"'rm -rf \""'$work_tmp"'"' EXIT
curl --insecure -L --fail --show-error --silent --max-time 40 'https://highereducation.mp.gov.in/?orgid=263' -o \""'$work_tmp/home.html"
python3 - "$work_tmp/home.html" <<'"'PY'
import sys
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.out=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
 def handle_endtag(self,t):
  if t in ('script','style') and self.skip: self.skip-=1
 def handle_data(self,d):
  if not self.skip and d.strip(): self.out.append(' '.join(d.split()))
p=P(); p.feed(open(sys.argv[1]).read())
for i,x in enumerate(p.out): print(f'{i:03d}: {x}')
PY"

