import sys,re
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
 def __init__(self): super().__init__(); self.table=0; self.row=[]; self.rows=[]; self.cell=[]; self.incell=False
 def handle_starttag(self,t,a):
  if t=='table': self.table+=1
  if t=='tr' and self.table: self.row=[]
  if t in ('td','th') and self.table: self.cell=[]; self.incell=True
 def handle_endtag(self,t):
  if t in ('td','th') and self.incell: self.row.append(' '.join(''.join(self.cell).split())); self.incell=False
  if t=='tr' and self.table and self.row: self.rows.append((self.table,self.row))
  if t=='table': self.table-=1
 def handle_data(self,d):
  if self.incell: self.cell.append(d)
for fn in ['regular','distance']:
 p=P(); p.feed(Path(sys.argv[1],fn+'.html').read_text())
 print(fn)
 for t,row in p.rows:
  if row and row[0] not in ('Course Name',) and (row[0].startswith('B.') or row[0].startswith('M.')): print(t, row)
PY"

